import{_ as i,C as t,c as n,o as l,a9 as s,G as r}from"./chunks/framework.BMko4Wr3.js";const k=JSON.parse('{"title":"世界管理器创建世界","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/Terra"},{"title":"世界管理器创建世界","link":"/Terra/getting-started.bukkit-installation.worldmanager-world-creation"}]},"headers":[],"relativePath":"Terra/getting-started.bukkit-installation.worldmanager-world-creation.md","filePath":"Terra/getting-started.bukkit-installation.worldmanager-world-creation.md"}'),c={name:"Terra/getting-started.bukkit-installation.worldmanager-world-creation.md"};function d(p,e,u,m,g,_){const a=t("NolebaseGitContributors"),o=t("NolebaseGitChangelog");return l(),n("div",null,[e[0]||(e[0]=s('<h1 id="世界管理器创建世界" tabindex="-1">世界管理器创建世界 <a class="header-anchor" href="#世界管理器创建世界" aria-label="Permalink to &quot;世界管理器创建世界&quot;">​</a></h1><p>大部分世界管理器都有自己设置/修改世界生成器的方法，其中一些可能不支持使用自定义生成器。如果你不确定你使用的多世界插件是否支持自定义生成器，或不知道如何使用，请在联系 Terra 支持频道前查阅对应插件的文档。</p><p>世界管理插件种类繁多，我们不可能逐一列出讲述。如果你还不确定你想要使用哪个世界管理插件，我们在本教程中推荐使用 <a href="https://github.com/Multiverse/Multiverse-Core/wiki/" target="_blank" rel="noreferrer">Multiverse Core</a>。</p><div class="warning custom-block"><p class="custom-block-title">警告</p><p>有些时候，世界管理插件会在初始化时未能正确设置生成器，这可能导致世界存坏的相关问题，例如突兀的区块生成。</p><p>因此我们推荐在通过世界管理器设置后，<a href="./getting-started.bukkit-installation#世界创建">在 Bukkit 配置</a>再设置一次，以避免<strong>世界管理器出错</strong>时地形无法生成。</p></div><h2 id="multiverse-core" tabindex="-1">Multiverse Core <a class="header-anchor" href="#multiverse-core" aria-label="Permalink to &quot;Multiverse Core&quot;">​</a></h2><p>若要使用 Multiverse Core 创建 Terra 世界，请在 Multiverse 的<a href="https://github.com/Multiverse/Multiverse-Core/wiki/Command-Reference#create-command" target="_blank" rel="noreferrer">创建命令</a>后添加如下参数：</p><p><code>-g Terra:&lt;包 ID&gt;</code></p><p>Terra 自带一个主世界地形包，其 ID 为 <code>OVERWORLD</code>。如果你没有预先安装其他配置包，则请将 <code>&lt;包 ID&gt;</code> 替换为 <code>OVERWORLD</code>。</p><p>如下命令会创建名为 <code>example_world</code>，环境为 <code>NORMAL</code>，并使用默认 <code>OVERWORLD</code> 包的世界：</p><p><code>/mv create example_world NORMAL -g Terra:OVERWORLD</code></p><h2 id="问题排查" tabindex="-1">问题排查 <a class="header-anchor" href="#问题排查" aria-label="Permalink to &quot;问题排查&quot;">​</a></h2><p>如果你在世界设置过程中碰到了问题，请确保你仔细按照各个步骤进行了设置。在服务端日志中检查可能出现的报错，并尝试自行排除问题所在。</p><p>如果你未能成功创建世界，并且尝试自行解决无果，随时可以<a href="./contact-and-support">寻求帮助</a>并提供相关信息，尤其是上述的日志！</p>',13)),r(a),r(o)])}const b=i(c,[["render",d]]);export{k as __pageData,b as default};
